fn binary_search(a: &Vec<i32>, key: i32) -> usize {
    let mut low: usize = 0;
    let mut high: usize = a.len();

    // Invariant:
    //  0 <= low <= high <= a.len()
    // All indices < low have a[i] < key.
    // All indices >= high have a[i] >= key.
    while low < high {
        let mid = low + (high - low) / 2;
        if a[mid] < key {
            // key must be inserted after mid
            low = mid + 1;
        } else {
            // key could go at or before mid
            high = mid;
        }
    }

    // Now low == high, and it's the smallest index
    // such that every element before is < key,
    // and every element at or after is >= key.
    low
}

